using System;
using System.Net.Http;
using System.Threading.Tasks;
using Consul;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.CircuitBreaker;
using Polly.Extensions.Http;
using Polly.Timeout;

namespace MicroserviceCommunicationDemo
{
    // 服务发现抽象
    public interface IServiceDiscovery
    {
        Task<string> GetServiceUrlAsync(string serviceName);
    }

    public class ConsulServiceDiscovery : IServiceDiscovery
    {
        private readonly IConsulClient _consulClient;
        private readonly ILogger<ConsulServiceDiscovery> _logger;

        public ConsulServiceDiscovery(IConsulClient consulClient, ILogger<ConsulServiceDiscovery> logger)
        {
            _consulClient = consulClient;
            _logger = logger;
        }

        public async Task<string> GetServiceUrlAsync(string serviceName)
        {
            // 只查 healthy 实例
            var services = await _consulClient.Health.Service(serviceName, null, true);
            if (services.Response.Length == 0)
            {
                _logger.LogWarning("服务 {Service} 无健康实例", serviceName);
                return null;
            }

            // 简单随机负载均衡
            var idx = new Random().Next(services.Response.Length);
            var svc = services.Response[idx].Service;
            return $"http://{svc.Address}:{svc.Port}";
        }
    }

    // Polly 策略工厂
    public static class ResiliencePolicies
    {
        // 重试：指数退避 + 抖动，只重试瞬态错误
        public static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy(ILogger logger)
        {
            return HttpPolicyExtensions
                .HandleTransientHttpError()        // 5xx + HttpRequestException
                .Or<TimeoutRejectedException>()
                .WaitAndRetryAsync(
                    retryCount: 3,
                    sleepDurationProvider: retry => TimeSpan.FromSeconds(Math.Pow(2, retry))
                        + TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000)),
                    onRetry: (outcome, delay, attempt, ctx) =>
                        logger.LogWarning("重试第 {Attempt} 次，等待 {Delay}s", attempt, delay.TotalSeconds));
        }

        // 熔断器：5 次失败后打开 30 秒
        public static IAsyncPolicy<HttpResponseMessage> GetCircuitBreakerPolicy(ILogger logger)
        {
            return HttpPolicyExtensions
                .HandleTransientHttpError()
                .CircuitBreakerAsync(
                    handledEventsAllowedBeforeBreaking: 5,
                    durationOfBreak: TimeSpan.FromSeconds(30),
                    onBreak: (_, duration) => logger.LogWarning("熔断器打开 {Duration}s", duration.TotalSeconds),
                    onReset: () => logger.LogInformation("熔断器关闭"),
                    onHalfOpen: () => logger.LogInformation("熔断器半开放探测"));
        }

        // 超时：乐观模式，10 秒
        public static IAsyncPolicy<HttpResponseMessage> GetTimeoutPolicy()
        {
            return Policy.TimeoutAsync<HttpResponseMessage>(TimeSpan.FromSeconds(10));
        }

        // 舱壁隔离：最多 10 并发 + 25 排队
        public static IAsyncPolicy<HttpResponseMessage> GetBulkheadPolicy(ILogger logger)
        {
            return Policy.BulkheadAsync<HttpResponseMessage>(
                maxParallelization: 10,
                maxQueuingActions: 25,
                onBulkheadRejectedAsync: _ =>
                {
                    logger.LogWarning("请求被舱壁策略拒绝");
                    return Task.CompletedTask;
                });
        }
    }

    // 用户服务客户端
    public class UserServiceClient
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<UserServiceClient> _logger;

        public UserServiceClient(HttpClient httpClient, ILogger<UserServiceClient> logger)
        {
            _httpClient = httpClient;
            _logger = logger;
        }

        public async Task<User?> GetUserAsync(int id)
        {
            try
            {
                var response = await _httpClient.GetAsync($"/api/users/{id}");
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadFromJsonAsync<User>();
            }
            catch (BrokenCircuitException)
            {
                _logger.LogError("熔断器已打开，降级返回 null");
                return null; // 降级
            }
            catch (BulkheadRejectedException)
            {
                _logger.LogError("舱壁已满，降级返回 null");
                return null;
            }
        }
    }

    public record User(int Id, string Name, string Email);

    // DI 注册扩展
    public static class ServiceCollectionExtensions
    {
        public static IServiceCollection AddMicroserviceCommunication(this IServiceCollection services)
        {
            // Consul 客户端
            services.AddSingleton<IConsulClient>(sp =>
                new ConsulClient(c => c.Address = new Uri("http://localhost:8500")));
            services.AddSingleton<IServiceDiscovery, ConsulServiceDiscovery>();

            // HttpClient + Polly 策略链（顺序：超时→重试→熔断→舱壁）
            services.AddHttpClient<UserServiceClient>("user-service")
                .AddPolicyHandler((sp, _) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetTimeoutPolicy(); // 最外层
                })
                .AddPolicyHandler((sp, _) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetRetryPolicy(logger);
                })
                .AddPolicyHandler((sp, _) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetCircuitBreakerPolicy(logger);
                })
                .AddPolicyHandler((sp, _) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetBulkheadPolicy(logger);
                });

            return services;
        }

        // 服务注册/注销
        public static async Task RegisterServiceAsync(
            this IApplicationBuilder app, string name, string id,
            string address, int port, string healthUrl)
        {
            var client = app.ApplicationServices.GetRequiredService<IConsulClient>();
            await client.Agent.ServiceRegister(new AgentServiceRegistration
            {
                ID = id, Name = name, Address = address, Port = port,
                Check = new AgentServiceCheck
                {
                    HTTP = healthUrl,
                    Interval = TimeSpan.FromSeconds(10),
                    Timeout = TimeSpan.FromSeconds(5)
                }
            });
        }

        public static async Task DeregisterServiceAsync(this IApplicationBuilder app, string id)
        {
            var client = app.ApplicationServices.GetRequiredService<IConsulClient>();
            await client.Agent.ServiceDeregister(id);
        }
    }
}
